package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AprobacionCompraService {private final NivelAprobacionCompraRepository levels;private final AprobacionOrdenCompraRepository decisions;private final OrdenCompraRepository orders;private final AuditoriaService audit;
 @Transactional public NivelAprobacionCompra guardarNivel(NivelAprobacionCompra level){if(level.getAmountTo()!=null&&level.getAmountTo().compareTo(level.getAmountFrom())<0)throw new IllegalArgumentException("Rango de monto inválido");return levels.save(level);}
 @Transactional(readOnly=true) public List<NivelAprobacionCompra> niveles(){return levels.findByActiveTrueOrderByLevelAsc();}
 @Transactional public AprobacionOrdenCompra decidir(Long orderId,Long levelId,String decision,String comment){OrdenCompra o=orders.findDetailedById(orderId).orElseThrow(()->new ResourceNotFoundException("Orden no encontrada"));NivelAprobacionCompra l=levels.findById(levelId).orElseThrow(()->new ResourceNotFoundException("Nivel no encontrado"));if(!"PENDIENTE_APROBACION".equals(o.getStatus()))throw new IllegalArgumentException("La orden no requiere aprobación");if(!Set.of("APROBADA","RECHAZADA").contains(decision))throw new IllegalArgumentException("Decisión no válida");AprobacionOrdenCompra d=decisions.save(AprobacionOrdenCompra.builder().purchaseOrder(o).level(l).decision(decision).decidedAt(LocalDateTime.now()).comment(comment).build());if("RECHAZADA".equals(decision))o.setStatus("RECHAZADA");else if(decisions.countByPurchaseOrderIdAndLevelIdAndDecision(orderId,levelId,"APROBADA")>=l.getRequiredApprovals())o.setStatus("PENDIENTE");orders.save(o);audit.registrar("UPDATE","ORDEN_COMPRA",o.getId(),"Aprobación nivel "+l.getLevel()+": "+decision);return d;}
 @Transactional(readOnly=true) public List<AprobacionOrdenCompra> historial(Long orderId){return decisions.findByPurchaseOrderIdOrderByDecidedAtDesc(orderId);}}
